USE STUDENTDB;
USE EMPLOYEEDB;
USE SHOPPINGDB;
USE LIBRARYDB;
USE COLLEGEDB;
USE MOVIEDB;

-- Basic Subquery
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > (SELECT AVG(SALARY) FROM EMPLOYEES B);
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY < (SELECT AVG(SALARY) FROM EMPLOYEES B); 
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MAX(SALARY) FROM EMPLOYEES B);
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MIN(SALARY) FROM EMPLOYEES B);
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE > (SELECT AVG(PRICE) FROM PRODUCTS B);
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE < (SELECT AVG(PRICE) FROM PRODUCTS B);
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE > (SELECT AVG(PRICE) FROM BOOKS B);
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE < (SELECT AVG(PRICE) FROM BOOKS B);
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE > (SELECT AVG(AGE) FROM STUDENTS B);
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE < (SELECT AVG(AGE) FROM STUDENTS B);
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MAX(SALARY) FROM EMPLOYEES B);
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MIN(SALARY) FROM EMPLOYEES B);
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE = (SELECT MAX(PRICE) FROM PRODUCTS B);
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE = (SELECT MIN(PRICE) FROM PRODUCTS B);
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE = (SELECT MAX(PRICE) FROM BOOKS B);
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE = (SELECT MAX(AGE) FROM STUDENTS B);
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE = (SELECT MIN(AGE) FROM STUDENTS B);
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES > (SELECT AVG(FEES) FROM COURSES B);
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES < (SELECT AVG(FEES) FROM COURSES B);
SELECT A.TITLE, A.RATING FROM MOVIES A WHERE A.RATING > (SELECT AVG(RATING) FROM MOVIES B);

-- Subquery with IN
SELECT A.EMPLOYEE_NAME, A.DEPARTMENT FROM EMPLOYEES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM EMPLOYEES B WHERE B.EMPLOYEE_NAME='ANTONY');
SELECT A.STUDENT_NAME, A.DEPARTMENT FROM STUDENTS A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM STUDENTS B WHERE B.STUDENT_NAME='ANTONY');
SELECT A.PRODUCT_NAME, A.CATEGORY FROM PRODUCTS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM PRODUCTS B WHERE B.CATEGORY='LAPTOP');
SELECT A.BOOK_NAME, A.CATEGORY FROM BOOKS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM BOOKS B WHERE B.CATEGORY='SQL_BASICS');
SELECT A.EMPLOYEE_NAME, A.DEPARTMENT FROM EMPLOYEES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM EMPLOYEES B WHERE B.SALARY > 60000);
SELECT A.STUDENT_NAME, A.DEPARTMENT FROM STUDENTS A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM STUDENTS B WHERE B.AGE > 22);
SELECT A.PRODUCT_NAME, A.CATEGORY FROM PRODUCTS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM PRODUCTS B WHERE B.PRICE > 50000);
SELECT A.BOOK_NAME, A.CATEGORY FROM BOOKS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM BOOKS B WHERE B.PRICE > 1000);
SELECT A.EMPLOYEE_NAME, A.DEPARTMENT FROM EMPLOYEES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM EMPLOYEES B WHERE B.DESIGNATION='MANAGER');
SELECT A.COURSE_NAME, A.DEPARTMENT FROM COURSES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM COURSES B WHERE B.FEES > 50000);
SELECT A.STUDENT_NAME, A.DEPARTMENT FROM STUDENTS A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM STUDENTS B WHERE B.AGE > 25);
SELECT A.PRODUCT_NAME, A.CATEGORY FROM PRODUCTS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM PRODUCTS B WHERE B.AVAILABLE_STOCK > 100);
SELECT A.EMPLOYEE_NAME, A.DEPARTMENT FROM EMPLOYEES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM EMPLOYEES B WHERE B.SALARY > 70000);
SELECT A.BOOK_NAME, A.CATEGORY FROM BOOKS A WHERE A.CATEGORY IN (SELECT B.CATEGORY FROM BOOKS B WHERE B.PRICE > 1500);
SELECT A.CUSTOMER_NAME, A.CITY FROM CUSTOMERS A WHERE A.CITY IN (SELECT B.CITY FROM CUSTOMERS B WHERE B.STATE='TAMIL_NADU');
SELECT A.EMPLOYEE_NAME, A.DEPARTMENT FROM EMPLOYEES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM EMPLOYEES B WHERE B.SALARY < 30000);
SELECT A.STUDENT_NAME, A.DEPARTMENT FROM STUDENTS A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM STUDENTS B WHERE B.AGE BETWEEN 20 AND 25);
SELECT A.PRODUCT_NAME, A.BRAND FROM PRODUCTS A WHERE A.BRAND IN (SELECT B.BRAND FROM PRODUCTS B WHERE B.PRICE > 50000);
SELECT A.BOOK_NAME, A.AUTHOR FROM BOOKS A WHERE A.AUTHOR IN (SELECT B.AUTHOR FROM BOOKS B WHERE B.PRICE > 1000);
SELECT A.COURSE_NAME, A.DEPARTMENT FROM COURSES A WHERE A.DEPARTMENT IN (SELECT B.DEPARTMENT FROM COURSES B WHERE B.DURATION = 6);

-- Subquery with Aggregate Functions
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE B.DEPARTMENT='HR');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY < (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE B.DEPARTMENT='FINANCE');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE > (SELECT AVG(B.PRICE) FROM PRODUCTS B WHERE B.CATEGORY='ELECTRONICS');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE < (SELECT AVG(B.PRICE) FROM PRODUCTS B WHERE B.CATEGORY='ACCESSORIES');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE > (SELECT AVG(B.PRICE) FROM BOOKS B WHERE B.CATEGORY='TECHNOLOGY');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE < (SELECT AVG(B.PRICE) FROM BOOKS B WHERE B.CATEGORY='SCIENCE');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE > (SELECT AVG(B.AGE) FROM STUDENTS B WHERE B.DEPARTMENT='IT');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE < (SELECT AVG(B.AGE) FROM STUDENTS B WHERE B.DEPARTMENT='CSE');
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES > (SELECT AVG(B.FEES) FROM COURSES B WHERE B.DEPARTMENT='CSE');
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES < (SELECT AVG(B.FEES) FROM COURSES B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MAX(B.SALARY) FROM EMPLOYEES B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = (SELECT MIN(B.SALARY) FROM EMPLOYEES B WHERE B.DEPARTMENT='HR');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE = (SELECT MAX(B.PRICE) FROM PRODUCTS B WHERE B.CATEGORY='ELECTRONICS');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE = (SELECT MIN(B.PRICE) FROM PRODUCTS B WHERE B.CATEGORY='ACCESSORIES');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE = (SELECT MAX(B.PRICE) FROM BOOKS B WHERE B.CATEGORY='TECHNOLOGY');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE = (SELECT MAX(B.AGE) FROM STUDENTS B WHERE B.DEPARTMENT='IT');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE = (SELECT MIN(B.AGE) FROM STUDENTS B WHERE B.DEPARTMENT='CSE');
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES = (SELECT MAX(B.FEES) FROM COURSES B WHERE B.DEPARTMENT='CSE');
SELECT A.TITLE, A.RATING FROM MOVIES A WHERE A.RATING = (SELECT MAX(B.RATING) FROM MOVIES B);

-- Correlated Subquery
SELECT A.EMPLOYEE_NAME, A.SALARY, A.DEPARTMENT FROM EMPLOYEES A WHERE A.SALARY > (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.EMPLOYEE_NAME, A.SALARY, A.DEPARTMENT FROM EMPLOYEES A WHERE A.SALARY < (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.STUDENT_NAME, A.AGE, A.DEPARTMENT FROM STUDENTS A WHERE A.AGE > (SELECT AVG(B.AGE) FROM STUDENTS B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.STUDENT_NAME, A.AGE, A.DEPARTMENT FROM STUDENTS A WHERE A.AGE < (SELECT AVG(B.AGE) FROM STUDENTS B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.PRODUCT_NAME, A.PRICE, A.CATEGORY FROM PRODUCTS A WHERE A.PRICE > (SELECT AVG(B.PRICE) FROM PRODUCTS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.PRODUCT_NAME, A.PRICE, A.CATEGORY FROM PRODUCTS A WHERE A.PRICE < (SELECT AVG(B.PRICE) FROM PRODUCTS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.TITLE, A.PRICE, A.CATEGORY FROM BOOKS A WHERE A.PRICE > (SELECT AVG(B.PRICE) FROM BOOKS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.TITLE, A.PRICE, A.CATEGORY FROM BOOKS A WHERE A.PRICE < (SELECT AVG(B.PRICE) FROM BOOKS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.EMPLOYEE_NAME, A.SALARY, A.DEPARTMENT FROM EMPLOYEES A WHERE A.SALARY > (SELECT MIN(B.SALARY) FROM EMPLOYEES B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.EMPLOYEE_NAME, A.SALARY, A.DEPARTMENT FROM EMPLOYEES A WHERE A.SALARY = (SELECT MAX(B.SALARY) FROM EMPLOYEES B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.STUDENT_NAME, A.AGE, A.DEPARTMENT FROM STUDENTS A WHERE A.AGE = (SELECT MAX(B.AGE) FROM STUDENTS B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.STUDENT_NAME, A.AGE, A.DEPARTMENT FROM STUDENTS A WHERE A.AGE = (SELECT MIN(B.AGE) FROM STUDENTS B WHERE A.DEPARTMENT=B.DEPARTMENT);
SELECT A.PRODUCT_NAME, A.PRICE, A.CATEGORY FROM PRODUCTS A WHERE A.PRICE = (SELECT MAX(B.PRICE) FROM PRODUCTS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.PRODUCT_NAME, A.PRICE, A.CATEGORY FROM PRODUCTS A WHERE A.PRICE = (SELECT MIN(B.PRICE) FROM PRODUCTS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.TITLE, A.PRICE, A.CATEGORY FROM BOOKS A WHERE A.PRICE = (SELECT MAX(B.PRICE) FROM BOOKS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.TITLE, A.PRICE, A.CATEGORY FROM BOOKS A WHERE A.PRICE = (SELECT MIN(B.PRICE) FROM BOOKS B WHERE A.CATEGORY=B.CATEGORY);
SELECT A.EMPLOYEE_NAME, A.SALARY, A.DESIGNATION FROM EMPLOYEES A WHERE A.SALARY > (SELECT AVG(B.SALARY) FROM EMPLOYEES B WHERE A.DESIGNATION=B.DESIGNATION);
SELECT A.PRODUCT_NAME, A.PRICE, A.BRAND FROM PRODUCTS A WHERE A.PRICE > (SELECT AVG(B.PRICE) FROM PRODUCTS B WHERE A.BRAND=B.BRAND);
SELECT A.STUDENT_NAME, A.AGE, A.GENDER FROM STUDENTS A WHERE A.AGE > (SELECT AVG(B.AGE) FROM STUDENTS B WHERE A.GENDER=B.GENDER);
SELECT A.COURSE_NAME, A.FEES, A.DEPARTMENT FROM STUDENTS A WHERE A.FEES > (SELECT AVG(B.FEES) FROM STUDENTS B WHERE A.DEPARTMENT=B.DEPARTMENT);

-- Subquery with ANY and ALL
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > ANY (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DEPARTMENT='HR');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > ALL (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DEPARTMENT='HR');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY < ANY (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY < ALL (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DEPARTMENT='IT');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE > ANY (SELECT B.PRICE FROM PRODUCTS B WHERE B.CATEGORY='ELECTRONICS');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE > ALL (SELECT B.PRICE FROM PRODUCTS B WHERE B.CATEGORY='ELECTRONICS');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE < ANY (SELECT B.PRICE FROM BOOKS B WHERE B.CATEGORY='TECHNOLOGY');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE < ALL (SELECT B.PRICE FROM BOOKS B WHERE B.CATEGORY='TECHNOLOGY');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE > ANY (SELECT B.AGE FROM STUDENTS B WHERE B.DEPARTMENT='CSE');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE > ALL (SELECT B.AGE FROM STUDENTS B WHERE B.DEPARTMENT='CSE');
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES > ANY (SELECT B.FEES FROM COURSES B WHERE B.DEPARTMENT='IT');
SELECT A.COURSE_NAME, A.FEES FROM COURSES A WHERE A.FEES > ALL (SELECT B.FEES FROM COURSES B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY = ANY (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DESIGNATION='DEVELOPERS');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE = ANY (SELECT B.PRICE FROM PRODUCTS B WHERE B.BRAND='SAMSUNG');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE > ANY (SELECT B.PRICE FROM BOOKS B WHERE B.CATEGORY='SCIENCE');
SELECT A.TITLE, A.PRICE FROM BOOKS A WHERE A.PRICE > ALL (SELECT B.PRICE FROM BOOKS B WHERE B.CATEGORY='SCIENCE');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE < ANY (SELECT B.AGE FROM STUDENTS B WHERE B.DEPARTMENT='IT');
SELECT A.STUDENT_NAME, A.AGE FROM STUDENTS A WHERE A.AGE < ALL (SELECT B.AGE FROM STUDENTS B WHERE B.DEPARTMENT='IT');
SELECT A.EMPLOYEE_NAME, A.SALARY FROM EMPLOYEES A WHERE A.SALARY > ALL (SELECT B.SALARY FROM EMPLOYEES B WHERE B.DESIGNATION='TESTER');
SELECT A.PRODUCT_NAME, A.PRICE FROM PRODUCTS A WHERE A.PRICE > ALL (SELECT B.PRICE FROM PRODUCTS B WHERE B.CATEGORY='ACCESSORIES');